<!--vbase-->
<template>
  <div
    v-if="message !== ''"
    class="q-dialog fullscreen no-pointer-events q-dialog--modal banner-parent"
  >
    <div
      class="q-dialog__backdrop fixed-full"
      aria-hidden="true"
      style="--q-transition-duration: 300ms"
    ></div>
    <div class="lock-banner row q-dialog__inner all-pointer-events">
      <span class="left-side">
        <q-btn class="reload-doc text-weight-bold" to="/dashboard">
          {{ $t('dashboard') }}
        </q-btn>
      </span>

      <span class="message">
        {{ message }}
      </span>

      <span class="right-side">
        <q-btn
          v-if="unlock_btn"
          class="force-unlock text-weight-bold"
          @click="forceAcquireLock(true)"
        >
          {{ $t('unlock') }}
        </q-btn>
        <q-btn
          v-if="reload_btn"
          class="reload-doc text-weight-bold"
          @click="reloadDocument"
        >
          {{ $t('refresh') }}
        </q-btn>
      </span>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import docLock from 'src/utils/docLock';
import { defineComponent, ref } from 'vue';
import { objLen } from 'src/utils/general';
import { doc_lock_key, readOnlyDocStatus } from 'src/constants';
import { isUserAdmin } from 'src/utils/UserDetails';
import {
  useDocLockStore,
  // useDocPermissionsStore,
  useDocumentStore,
} from 'src/store/main';
import { documentSDK } from 'src/sdk/api/wrapper/DocumentSDK';
import cache from 'src/utils/cache';

export default defineComponent({
  el: '#app',
  mixins: [docLock, cache],
  emits: ['setTriggerDocumentLock'],
  props: {
    document_version: {
      type: Number,
      default: 0,
    },
    trigger_document_lock: {
      type: Boolean,
      default: false,
    },
    doc_id: {
      type: String,
      default: '',
    },
  },
  watch: {
    document_version: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.forceAcquireLock();
      },
    },
    trigger_document_lock(new_val: any, old_val: any) {
      if (new_val === true) {
        const doc_lock_store = useDocLockStore();

        if (this.unsubscribeDocLock) {
          this.unsubscribeDocLock();
        }

        this.unsubscribeDocLock = doc_lock_store.$subscribe(
          (mutation, state) => {
            this.afterAcquireLock();
          },
        );

        // Raising the flag is the parent's "acquire now" signal, so act on it
        // here. $subscribe never replays past mutations, so leaning on a
        // document_version change left the flag stuck true (and its banners
        // hidden): the version either never changed - document.store.ts falls
        // back to 0 where MediOrder's setDocVersion falls back to 1 - or changed
        // during the fetch, before the flag went up, so the emit was lost.
        if (this.doc_lock?.success === true) {
          this.afterAcquireLock();
        } else {
          this.forceAcquireLock();
        }
      } else {
        if (this.unsubscribeDocLock) {
          this.unsubscribeDocLock();
          this.unsubscribeDocLock = null;
        }
      }
    },
  },
  unmounted() {
    window.removeEventListener('pagehide', this.unLockDoc);
    if (this.unsubscribeDocLock) {
      this.unsubscribeDocLock();
      this.unsubscribeDocLock = null;
    }
  },
  mounted() {
    window.addEventListener('pagehide', this.unLockDoc);
  },
  components: {},
  data() {
    return {
      unsubscribeDocLock: null as unknown as (() => void) | null,
      // Collapses duplicate concurrent acquires - see forceAcquireLock.
      acquiringLock: false,
      // DOCB-11039: re-entrancy guard for the self-heal path below so an
      // in-flight forced re-acquire doesn't get triggered again by the
      // doc_lock store mutation it itself causes.
      selfHealingLock: false,
    };
  },
  methods: {
    async forceAcquireLock(force = false) {
      if (readOnlyDocStatus.includes(this.record.status)) {
        force = true;
      }

      // Prop watchers are batched, so a parent assigning document_version and
      // trigger_document_lock in one tick (MediOrder's init) fires both watchers
      // in the same flush. Collapse the duplicate; the in-flight call still runs
      // afterAcquireLock() for everyone.
      if (this.acquiringLock) {
        return;
      }
      this.acquiringLock = true;
      try {
        if (this.doc_id) {
          await this.acquireDocLock(
            force,
            this.record.doc_id,
            this.document_version.toString(),
          );
        } else {
          await this.acquireDocLock(force);
        }
      } finally {
        this.acquiringLock = false;
      }
      this.afterAcquireLock();
    },

    async afterAcquireLock() {
      this.setDataToSessionStorage(doc_lock_key, this.doc_lock?.key);
      if (this.doc_lock?.success === true) {
        this.message = '';
      }
      if (
        this.doc_lock?.success === false &&
        objLen(this.doc_lock?.error) !== 0
      ) {
        const error_code = String(
          this.doc_lock?.error?.error_code || '',
        ).toLowerCase();

        // DOCB-11039: "document_already_modified" raised against the current
        // user's own prior write (e.g. Table Tags Apply advancing the
        // document version without syncing it back locally first) is not a
        // concurrent edit by someone else — it's this session's own change
        // being echoed back. Self-heal by silently re-acquiring the lock
        // (which adopts the current version) instead of surfacing the
        // external-modification banner and blanking the viewer. A genuinely
        // different user's edit never satisfies the self-check in
        // getTranslationKeyForDocLockError and still falls through to the
        // banner below.
        if (
          error_code === 'document_already_modified' &&
          this.getTranslationKeyForDocLockError(this.doc_lock.error).endsWith(
            '_by_same_user',
          )
        ) {
          this.message = '';
          this.removeBaner();
          if (!this.selfHealingLock) {
            this.selfHealingLock = true;
            try {
              await this.forceAcquireLock(true);
            } finally {
              this.selfHealingLock = false;
            }
          }
          return;
        }

        this.unlock_btn = false;
        this.reload_btn = false;

        // unlock_document permission disabled — only admins can unlock now.
        // this.unlock_role = await this.getUnlockRole(
        //   this.record.doc_type,
        //   this.record.assigned_to,
        // );

        if (error_code === 'document_already_modified') {
          this.reload_btn = true;
        }

        if (
          error_code === 'document_already_locked' &&
          (isUserAdmin() || this.unlock_role)
        ) {
          this.unlock_btn = true;
        }

        this.message = this.docLockErrorHandler(this.doc_lock?.error);
      }
      this.removeBaner();
    },

    async reloadDocument() {
      await documentSDK.clearExtractedDataCache(this.record.doc_id);
      await this.removeCache();
      this.$router.go(0);
    },

    removeBaner() {
      if (!this.message) {
        this.$emit('setTriggerDocumentLock', false);
      }
    },

    unLockDoc() {
      this.releaseDocLock({ doc_id: this.record.doc_id });
    },
  },
  setup() {
    const doc_lock_store = useDocLockStore();
    const { acquireDocLock, releaseDocLock } = doc_lock_store;
    const { doc_lock } = storeToRefs(doc_lock_store);

    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);
    const { removeCache } = doc_store;

    // const permission_store = useDocPermissionsStore();
    // const { getUnlockRole } = permission_store;
    return {
      removeCache,
      record,
      message: ref(''),
      unlock_btn: ref(false),
      unlock_role: ref(false),
      reload_btn: ref(false),
      doc_lock,
      acquireDocLock,
      releaseDocLock,
      // getUnlockRole,
    };
  },
});
</script>

