import { getUserDetailFromkey } from 'src/utils/UserDetails';
import { i18n } from 'src/boot/i18n';
import { date } from 'quasar';
export default {
  methods: {
    docLockNotify(id) {
      // this.showFullWidthToast(acquire_lock['error'], 'negative', true)
    },

    getTranslationKeyForDocLockError(data) {
      const id = getUserDetailFromkey('id');
      let translation_key = String(data.error_code);
      let doc_lock_user = '';

      // The backend echoes the acting user's stable id under different keys
      // depending on error_code: `locked_by_user` for document_already_locked,
      // `modified_by_user` for document_already_modified. Only `locked_by_user`
      // was ever checked here, so a self-caused "document already modified"
      // (e.g. Table Tags Apply racing the local doc_version) could never be
      // recognised as our own change and always rendered as an external
      // modification banner (DOCB-11039). Check both id fields, keyed off
      // which one the current error payload actually carries.
      if (data.hasOwnProperty('modified_by_user')) {
        doc_lock_user = data.modified_by_user;
      } else if (data.hasOwnProperty('locked_by_user')) {
        doc_lock_user = data.locked_by_user;
      }

      if (id !== '' && id == doc_lock_user) {
        translation_key += '_by_same_user';
      }

      return translation_key;
    },

    docLockErrorHandler(data) {
      let errro_code = '';
      if (data && data.hasOwnProperty('error_code')) {
        errro_code = data.error_code;
      }

      let translation_key = this.getTranslationKeyForDocLockError(data);

      let msg = this.docLockErrorTranslation(translation_key);
      msg = msg === data.error_code ? data.message : msg;

      let user = '';
      let locked_on = '';
      let corrected_time = '';
      if (data.hasOwnProperty('locked_by')) {
        user = data.locked_by;
      }

      if (data.hasOwnProperty('locked_on')) {
        locked_on = data.locked_on;
      }

      if (data.hasOwnProperty('modified_by')) {
        user = data.modified_by;
      }

      if (data.hasOwnProperty('modified_on')) {
        locked_on = data.modified_on;
      }

      msg = msg.replaceAll('%name', user);
      msg = msg.replaceAll(
        '%date',
        this.formateDate(
          new Date(`${locked_on} UTC+2`),
          'YYYY-MM-DD, HH:mm:ss',
        ),
      );

      // DOCB-13998: only fall back to the backend's raw `message` when our
      // own translation is unusable. This used to fire whenever `locked_by`
      // /`locked_on` were blank and unconditionally overwrite `msg` with
      // `data.message` — but `locked_by` is ALWAYS blank for the
      // "_by_same_user" variant (its translation text doesn't even use
      // %name, e.g. "Document is locked by your user in another session
      // at %date."), and the backend leaves `message` empty for that case
      // since it expects the frontend translation to supply the text. The
      // result was a perfectly good, already-interpolated message getting
      // silently replaced by an empty string — producing a fully blank
      // lock banner when the same user opened the same document in a
      // second session. Guard against overwriting a valid message with a
      // falsy one; still allow the raw backend message through when it's
      // genuinely non-empty and our translation needed data we didn't have.
      if ((user === '' || locked_on === '') && data.message) {
        msg = data.message;
      }

      return msg;
    },
    docLockErrorTranslation(translation_key) {
      let translation = '';
      try {
        translation = !translation_key ? '' : i18n.t(translation_key);
      } catch (err) {
        logError(err);
      }
      return translation;
    },
    formateDate(strDate, dateFormet) {
      return date.formatDate(strDate, dateFormet);
    },
  },
};
